package app;
import config.SimulationConfig;
import logging.Logger;
import model.*;
import java.util.*;

public class VerifyHarness {
	static String runTrajectory(SpeciesRegistry reg){
		int depth=200,width=320; Random rand=config.Randomizer.getRandom();
		Field field=new Field(depth,width); Climate climate=new Climate(Weather.SUN);
		List<Animal> animals=new ArrayList<>(); List<Plant> plants=new ArrayList<>(); field.clear();
		for(int r=0;r<depth;r++)for(int c=0;c<width;c++){Location loc=new Location(r,c);
			plants.add(reg.spawnPlant(rand,field,loc)); Animal an=reg.spawnAnimal(rand,field,loc); if(an!=null)animals.add(an);}
		TimeCycle cyc=TimeCycle.DAY; int step=0; StringBuilder sig=new StringBuilder();
		for(int s=1;s<=160;s++){step++; climate.updateClimate(step);
			for(Plant p:plants)p.increaseStage(climate); List<Animal> born=new ArrayList<>();
			for(Animal an:animals)an.act(born,cyc); animals.removeIf(an->!an.isAlive()); animals.addAll(born);
			if(step%4==0)cyc=cyc.next();
			if(s%10==0){TreeMap<String,Integer> ct=new TreeMap<>(); int sick=0;
				for(Animal an:animals){ct.merge(an.getClass().getSimpleName(),1,Integer::sum); if(an.isSick())sick++;}
				sig.append(String.format("s=%d pop=%d %s sick=%d season=%s wx=%s hum=%d cyc=%s%n",s,animals.size(),ct,sick,
					climate.getCurrentSeason(),climate.getCurrentWeather(),climate.getHumidity(),cyc));}}
		return sig.toString();
	}
	public static void main(String[] a){
		Logger log = msg -> System.err.println("[cfg] " + msg);   // capture loadConfig message to stderr
		// Use Main's REAL wiring: load simulation.properties + catalog -> registry
		SimulationConfig cfg = Main.loadConfig(log);
		System.err.println("[cfg] depth="+cfg.fieldDepth()+" width="+cfg.fieldWidth()
			+" animals="+cfg.animalRules()+" plants="+cfg.plantRules()+" default="+cfg.defaultPlant());
		SpeciesRegistry reg = Main.buildRegistry(cfg, new SpeciesCatalog());
		System.out.print(runTrajectory(reg));
	}
}
