public class ConfigTest {
	static long popAfter50(SpeciesRegistry reg){
		Random rand=config.Randomizer.getRandom();
		Field field=new Field(80,80); Climate climate=new Climate(Weather.SUN);
		List<Animal> animals=new ArrayList<>(); List<Plant> plants=new ArrayList<>(); field.clear();
		Set<String> seen=new TreeSet<>();
		for(int r=0;r<80;r++)for(int c=0;c<80;c++){Location loc=new Location(r,c);
			plants.add(reg.spawnPlant(rand,field,loc)); Animal an=reg.spawnAnimal(rand,field,loc);
			if(an!=null){animals.add(an); seen.add(an.getClass().getSimpleName());}}
		System.out.println("   species spawned: " + seen);
		return animals.size();
	}
	public static void main(String[] a) throws Exception {
		// (1) defaults() fallback builds a valid registry
		SpeciesRegistry def = Main.buildRegistry(SimulationConfig.defaults(), new SpeciesCatalog());
		System.out.println("(1) defaults() registry OK -> "+(def!=null));

		// (2) a MODIFIED config (only Bird + Mouse, tweaked probs) changes the outcome
		Path tmp = Files.createTempFile("sim", ".properties");
		Files.writeString(tmp, String.join("\n",
			"field.depth=80","field.width=80",
			"plant.order=Flower","plant.Flower.probability=0.10","plant.default=Grass",
			"animal.order=Bird,Mouse","animal.Bird.probability=0.20","animal.Mouse.probability=0.10"));
		SimulationConfig custom = SimulationConfig.load(tmp);
		System.out.println("(2) custom config animals="+custom.animalRules());
		SpeciesRegistry reg = Main.buildRegistry(custom, new SpeciesCatalog());
		popAfter50(reg);
		Files.delete(tmp);

		// (3) unknown species -> clear error
		try {
			Properties p = new Properties();
			p.setProperty("animal.order","Dragon");
			p.setProperty("animal.Dragon.probability","0.5");
			Main.buildRegistry(SimulationConfig.fromProperties(p), new SpeciesCatalog());
			System.out.println("(3) FAIL: expected exception");
		} catch (IllegalArgumentException e) {
			System.out.println("(3) unknown species rejected -> \""+e.getMessage()+"\" OK");
		}

